const g4 = createGate({ limit: 1, windowMs: 200, maxWaitMs: 40 });
await g4.acquire(1);
await assert.rejects(g4.acquire(1), (e) => e instanceof QuotaExceededError && e.code === 'WAIT_EXPIRED');
assert.equal(g4.stats().expired, 1);
assert.equal(g4.stats().waiting, 0);

// 8. expiry judged before allocation at flip boundary
const g5 = createGate({ limit: 1, windowMs: 50, maxWaitMs: 50 });
await g5.acquire(1);
const t0 = Date.now();
const pExp = g5.acquire(1); // deadline ~= flip time
await assert.rejects(pExp, (e) => e.code === 'WAIT_EXPIRED');
assert.equal(g5.stats().expired, 1);
assert.equal(g5.stats().granted, 1);

// 9. release from old window is inert after flip
const g6 = createGate({ limit: 2, windowMs: 40 });
const hOld = await g6.acquire(2);
await sleep(60);
hOld.release();
assert.equal(g6.stats().inFlight, 0);
const hNew = await g6.acquire(1);
hOld.release(); // must not touch new window's inFlight
assert.equal(g6.stats().inFlight, 1);
hNew.release();
assert.equal(g6.stats().inFlight, 0);

// 10. default units = 1
const g7 = createGate({ limit: 1, windowMs: 50 });
await g7.acquire();
assert.equal(g7.stats().inFlight, 1);

